+// descuentoGlobal: porcentaje (0 a 100) sobre el total de las líneas, redondeado al centavo; el IVA se
+// informa sobre el total ya descontado.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
+  if (typeof descuentoGlobal !== "number" || !Number.isFinite(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100)
+    throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
   let totalCentavos = 0;
   for (const item of items) {
@@ -17,6 +21,7 @@ export function calcularFactura(items) {
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
     totalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  totalCentavos -= Math.round((totalCentavos * descuentoGlobal) / 100);
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }
