+test("descuento global: porcentaje sobre el total, antes de informar el IVA", () => {
+  const items = [{ cantidad: 2, precioUnitarioCentavos: 1000 }];
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), { totalCentavos: 1800, ivaCentavos: 234, netoCentavos: 1566 });
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 0 }), calcularFactura(items));
+  assert.equal(calcularFactura(items, { descuentoGlobal: 100 }).totalCentavos, 0);
+  // redondeo al centavo: 333 * 15 % = 49,95 -> 50 centavos
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333 }], { descuentoGlobal: 15 }).totalCentavos, 283);
+  for (const malo of [-1, 100.5, NaN, "10"]) assert.throws(() => calcularFactura(items, { descuentoGlobal: malo }), RangeError);
+});
